"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { CalendarRange, CheckCircle2, FileSpreadsheet, ShieldCheck } from "lucide-react";
import { setPendingSpreadsheetFile, takePendingSpreadsheetFile } from "@/src/lib/spreadsheet-import-draft";

function todayLocalDateValue() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function addDaysDateValue(baseIso: string, days: number) {
  const d = new Date(`${baseIso}T00:00:00`);
  d.setDate(d.getDate() + days);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

export function ImportSpreadsheetClient() {
  const router = useRouter();
  const [file, setFile] = useState<File | null>(() => takePendingSpreadsheetFile());
  const [periodFrom, setPeriodFrom] = useState(() => todayLocalDateValue());
  const [periodTo, setPeriodTo] = useState(() => addDaysDateValue(todayLocalDateValue(), 27));
  const [importMissingEmployees, setImportMissingEmployees] = useState(true);
  const [insertShifts, setInsertShifts] = useState(true);
  const [runEuComplianceCheck, setRunEuComplianceCheck] = useState(true);
  const [started, setStarted] = useState(false);

  const canStart = useMemo(
    () =>
      file !== null &&
      periodFrom.length > 0 &&
      periodTo.length > 0 &&
      periodFrom <= periodTo &&
      (importMissingEmployees || insertShifts || runEuComplianceCheck),
    [file, periodFrom, periodTo, importMissingEmployees, insertShifts, runEuComplianceCheck]
  );

  return (
    <div className="flex min-h-full flex-1 flex-col bg-zinc-50 px-3 py-6 dark:bg-zinc-950 sm:px-4 sm:py-8">
      <div className="mx-auto w-full max-w-3xl space-y-6">
        <header className="space-y-2">
          <h1 className="text-2xl font-semibold tracking-tight text-zinc-900 dark:text-zinc-50">
            Hent regneark
          </h1>
          <p className="text-sm leading-relaxed text-zinc-600 dark:text-zinc-400">
            Upload dit Excel-ark og vælg fokusperiode. Vi hjælper dig trin for trin med at
            importere manglende medarbejdere, indsætte vagter og tjekke EU-arbejdsregler.
          </p>
        </header>

        <section className="rounded-xl border border-zinc-200 bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900">
          <label className="block">
            <span className="mb-2 flex items-center gap-2 text-sm font-semibold text-zinc-800 dark:text-zinc-200">
              <FileSpreadsheet className="h-4 w-4" aria-hidden />
              Vælg regneark (.xls / .xlsx)
            </span>
            <input
              type="file"
              accept=".xls,.xlsx,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
              onChange={(e) => {
                const nextFile = e.target.files?.[0] ?? null;
                setFile(nextFile);
                setPendingSpreadsheetFile(nextFile);
              }}
              className="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm text-zinc-800 dark:border-zinc-700 dark:bg-zinc-950 dark:text-zinc-100"
            />
          </label>
          <p className="mt-2 text-xs text-zinc-500 dark:text-zinc-400">
            {file ? `Valgt fil: ${file.name}` : "Ingen fil valgt endnu."}
          </p>
        </section>

        <section className="rounded-xl border border-zinc-200 bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900">
          <h2 className="mb-3 flex items-center gap-2 text-sm font-semibold uppercase tracking-wide text-zinc-500">
            <CalendarRange className="h-4 w-4" aria-hidden />
            Fokusperiode
          </h2>
          <div className="grid gap-3 sm:grid-cols-2">
            <label className="block">
              <span className="mb-1 block text-xs font-medium text-zinc-600 dark:text-zinc-300">
                Fra dato
              </span>
              <input
                type="date"
                value={periodFrom}
                onChange={(e) => setPeriodFrom(e.target.value)}
                className="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm dark:border-zinc-700 dark:bg-zinc-950"
              />
            </label>
            <label className="block">
              <span className="mb-1 block text-xs font-medium text-zinc-600 dark:text-zinc-300">
                Til dato
              </span>
              <input
                type="date"
                value={periodTo}
                onChange={(e) => setPeriodTo(e.target.value)}
                className="w-full rounded-lg border border-zinc-300 bg-white px-3 py-2 text-sm dark:border-zinc-700 dark:bg-zinc-950"
              />
            </label>
          </div>
        </section>

        <section className="rounded-xl border border-zinc-200 bg-white p-5 dark:border-zinc-800 dark:bg-zinc-900">
          <h2 className="mb-3 text-sm font-semibold uppercase tracking-wide text-zinc-500">
            Importhandlinger
          </h2>
          <div className="space-y-2 text-sm text-zinc-700 dark:text-zinc-200">
            <label className="flex items-start gap-2">
              <input
                type="checkbox"
                checked={importMissingEmployees}
                onChange={(e) => setImportMissingEmployees(e.target.checked)}
                className="mt-0.5 rounded border-zinc-300"
              />
              <span>Importer medarbejdere, som ikke allerede findes</span>
            </label>
            <label className="flex items-start gap-2">
              <input
                type="checkbox"
                checked={insertShifts}
                onChange={(e) => setInsertShifts(e.target.checked)}
                className="mt-0.5 rounded border-zinc-300"
              />
              <span>Indsæt vagter i kalenderen for den valgte periode</span>
            </label>
            <label className="flex items-start gap-2">
              <input
                type="checkbox"
                checked={runEuComplianceCheck}
                onChange={(e) => setRunEuComplianceCheck(e.target.checked)}
                className="mt-0.5 rounded border-zinc-300"
              />
              <span className="inline-flex items-center gap-1">
                <ShieldCheck className="h-4 w-4" aria-hidden />
                Kør EU-regelcheck (fx hviletid / overlap)
              </span>
            </label>
          </div>
        </section>

        <div className="flex flex-wrap gap-3">
          <button
            type="button"
            disabled={!canStart}
            onClick={() => setStarted(true)}
            className="rounded-lg bg-emerald-600 px-4 py-2.5 text-sm font-semibold text-white transition hover:bg-emerald-700 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Start import
          </button>
          <button
            type="button"
            onClick={() => router.push("/dashboard")}
            className="rounded-lg border border-zinc-300 px-4 py-2.5 text-sm font-semibold text-zinc-700 transition hover:bg-zinc-100 dark:border-zinc-700 dark:text-zinc-200 dark:hover:bg-zinc-800"
          >
            Til kalender
          </button>
        </div>

        {started ? (
          <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900 dark:border-emerald-900/40 dark:bg-emerald-950/30 dark:text-emerald-100">
            <p className="inline-flex items-center gap-2 font-semibold">
              <CheckCircle2 className="h-4 w-4" aria-hidden />
              Importforløb startet for perioden {periodFrom} til {periodTo}.
            </p>
            <p className="mt-2">
              Næste skridt: vi validerer filen, opretter manglende medarbejdere, indsætter vagter
              og viser efterfølgende et samlet EU-compliance resultat.
            </p>
          </div>
        ) : null}
      </div>
    </div>
  );
}
